            Method registerMethod = curiosRendererRegistryClass.getMethod("register", Item.class, Supplier.class);
            Supplier<Object> strawHatRenderer = () -> {
                try {
                    return strawHatCurioRendererClass.getConstructor(ModelPart.class).newInstance(Minecraft.m_91087_().m_167973_().m_171103_(StrawHatModel.LAYER_LOCATION));
                }
                catch (Exception e) {
                    return null;
                }
            };
            registerMethod.invoke(null, ModItems.STRAW_HAT.get(), strawHatRenderer);
            registerMethod.invoke(null, ModItems.STRAW_HAT_FLOWER.get(), strawHatRenderer);
        }
        catch (Exception exception) {
            // empty catch block
        }
    }

